// W1 - Step 1: Validate Incident Payload
const raw = $input.first().json;
const payload = raw.body || raw;
const incident = payload.incident || payload;

if (!incident.id && !incident.code) {
  incident.id = 'inc-' + Date.now();
}
incident.code = incident.code || incident.id || 'INC-2026';
incident.severity = incident.severity || 'CRITICAL';

return [{
  json: {
    isValid: true,
    validatedAt: new Date().toISOString(),
    incident: {
      id: incident.id,
      code: incident.code,
      title: incident.title || 'Disaster Event',
      severity: incident.severity,
      status: incident.status || 'REPORTED',
      primaryLocation: incident.primaryLocation || { name: incident.location || 'Sector Alpha', coordinates: [13.01, 80.23] },
      metrics: incident.metrics || { waterLevelMeters: 2.4, affectedPopulationEstimated: 1200 }
    },
    responsePlan: payload.responsePlan || null,
    resources: payload.resources || null,
    simulationMode: payload.simulationMode !== undefined ? payload.simulationMode : true,
    action: payload.action || 'TRIGGER_FULL_ORCHESTRATION'
  }
}];

// W1 - Step 2: Create / Update Incident in Workflow Context
const data = $input.first().json;
const incident = data.incident;

const normalizedRecord = {
  incidentId: incident.id,
  code: incident.code,
  intakeTimestamp: new Date().toISOString(),
  severity: incident.severity,
  waterLevel: incident.metrics?.waterLevelMeters || 2.4,
  affectedPopulation: incident.metrics?.affectedPopulationEstimated || 1200,
  status: 'REGISTERED_IN_WORKFLOW_ORCHESTRATOR'
};

return [{
  json: {
    ...data,
    normalizedRecord,
    workflowStage: 'INCIDENT_INTAKE_COMPLETED'
  }
}];

// W1 - Step 3: Analyze Severity
const data = $input.first().json;
const severity = (data.incident?.severity || 'MEDIUM').toUpperCase();

const isCritical = severity === 'CRITICAL' || severity === 'CATASTROPHIC' || severity === 'HIGH';

return [{
  json: {
    ...data,
    analysis: {
      severity,
      isCritical,
      requiresImmediateEocApproval: isCritical,
      recommendedAction: isCritical ? 'ESCALATE_TO_CRITICAL_RESPONSE' : 'ROUTE_TO_STANDARD_MONITORING'
    }
  }
}];

// W2 - Step: Allocate Resources (Intelligent Allocation Logic)
const payload = $input.first().json.body || $input.first().json;
const incident = payload.incident || {};
const requested = payload.responsePlan?.resourceAllocation || { ambulances: 2, rescueTeams: 2, drones: 1 };

const allocated = {
  incidentId: incident.id || 'INC-ACTIVE',
  assignedAmbulances: requested.ambulances || 2,
  assignedRescueTeams: requested.rescueTeams || 2,
  assignedDrones: requested.drones || 1,
  priorityZone: incident.primaryLocation?.name || incident.location || 'Zone A',
  allocationTimestamp: new Date().toISOString(),
  status: 'ALLOCATED_BY_N8N'
};

return [{
  json: {
    ...payload,
    allocated,
    prototypeDisclaimer: 'PROTOTYPE DEMONSTRATION: External real emergency services are not connected. Dispatch actions are simulated via mock endpoints.'
  }
}];

// W2 - Step: Trigger Drone Workflow Sub-Execution
const data = $input.first().json;

const droneMission = {
  droneCallsign: 'UAV-Echo-1',
  model: 'Matrice 300 RTK',
  missionType: 'THERMAL_SEARCH_CORRIDOR',
  targetZone: data.allocated?.priorityZone || 'Zone A',
  status: 'MISSION_CREATED',
  airborneAt: new Date().toISOString(),
  telemetryStreamActive: true
};

return [{
  json: {
    ...data,
    droneMission
  }
}];

// W3 - Step 1: Check Available Drones
const payload = $input.first().json.body || $input.first().json;
const drones = payload.resources?.drones || [
  {
    id: 'drone-101',
    callsign: 'UAV Echo-1',
    model: 'Matrice 300 RTK',
    flightStatus: 'STANDBY_PAD',
    batteryPercentage: 94,
    role: 'THERMAL_RECON'
  },
  {
    id: 'drone-102',
    callsign: 'UAV Talon-2',
    model: 'Mavic 3 Thermal',
    flightStatus: 'STANDBY_PAD',
    batteryPercentage: 88,
    role: 'SEARCH_AND_RESCUE'
  },
  {
    id: 'drone-103',
    callsign: 'UAV Lifeline-3',
    model: 'Heavy-Lift Octocopter',
    flightStatus: 'STANDBY_PAD',
    batteryPercentage: 76,
    role: 'SUPPLY_AIRDROP'
  }
];

const availableDrones = drones.filter(d => 
  (d.batteryPercentage || 90) > 30 && 
  (d.flightStatus === 'STANDBY_PAD' || d.flightStatus === 'READY' || d.flightStatus === 'STANDBY' || !d.flightStatus)
);

return [{
  json: {
    ...payload,
    totalFleetCount: drones.length,
    availableDrones,
    hasAvailableDrone: availableDrones.length > 0
  }
}];

// W3 - Step 2: Select Available Drone
const data = $input.first().json;
const available = data.availableDrones || [];

const selectedDrone = available.length > 0 
  ? [...available].sort((a, b) => b.batteryPercentage - a.batteryPercentage)[0]
  : { id: 'drone-101', callsign: 'UAV Echo-1', model: 'Matrice 300 RTK', batteryPercentage: 94 };

return [{
  json: {
    ...data,
    selectedDrone
  }
}];

// W3 - Step 3: Create Mission
const data = $input.first().json;
const drone = data.selectedDrone;
const targetZone = data.incident?.primaryLocation?.name || data.allocated?.priorityZone || 'Zone A';

const mission = {
  missionId: `MSN-${Date.now().toString(36).toUpperCase()}`,
  droneId: drone.id,
  droneCallsign: drone.callsign,
  model: drone.model,
  targetZone,
  flightPattern: 'PERIMETER_GRID_RECON',
  targetAltitudeMeters: 45,
  payload: 'Thermal FLIR + Floatation Vest Drop',
  flightStatus: 'MISSION_CREATED',
  createdAt: new Date().toISOString()
};

return [{
  json: {
    ...data,
    mission
  }
}];

// W3 - Step 4: Update Mission Status (Takeoff clearance)
const data = $input.first().json;

const updatedMission = {
  ...data.mission,
  flightStatus: 'AIRBORNE_PATROL',
  groundSpeedKmH: 38.5,
  telemetryLinkStrength: 98,
  clearedAt: new Date().toISOString()
};

return [{
  json: {
    ...data,
    mission: updatedMission,
    droneWorkflowStatus: 'IN_FLIGHT'
  }
}];

// W4 - Step 1: Generate Alert (CAP Protocol)
const payload = $input.first().json.body || $input.first().json;
const incident = payload.incident || {};
const zone = incident.primaryLocation?.name || payload.allocated?.priorityZone || 'Zone A';

const alertPayload = {
  alertId: `CAP-${incident.code || 'ALERT'}-${Date.now().toString(36).toUpperCase()}`,
  headline: `URGENT FLOOD EVACUATION: ${zone}`,
  severity: 'Extreme',
  urgency: 'Immediate',
  certainty: 'Observed',
  instruction: `Water level surge detected. Evacuate via Route R4 highland arterial. Avoid low-lying river bridges.`,
  targetPolygons: [zone],
  generatedAt: new Date().toISOString()
};

return [{
  json: {
    ...payload,
    alertPayload
  }
}];

// W4 - Step 3: Log Alert to Audit Ledger
const data = $input.first().json;

const auditLog = {
  auditId: `AUDIT-ALT-${Date.now()}`,
  alertId: data.alertPayload?.alertId,
  status: 'SIMULATION_BROADCAST_CONFIRMED',
  loggedAt: new Date().toISOString(),
  disclaimer: 'Prototype simulation: no real EAS broadcast.'
};

return [{
  json: {
    ...data,
    auditLog,
    emergencyAlert: 'SIMULATED'
  }
}];
